mapper.select:
SELECT c.id, c.change_set_id, c.run_id, c.step_id, c.user_id, c.project_id, c.chapter_id, c.kind,
       c.schema_version, c.instruction, c.status, c.base_project_revision, c.base_chapter_revision,
       c.before_json, c.payload_json, c.result_json, c.created_at, c.updated_at, c.created_by, c.updated_by
FROM manga_creative_change_set c JOIN manga_creative_run r ON r.run_id = c.run_id
WHERE c.user_id = #{userId} AND c.status != 'DRAFT'
AND c.run_id = #{runId}
AND r.conversation_id = #{conversationId}
AND c.id < #{beforeId}
ORDER BY c.id DESC LIMIT #{limit}
